var password = new ArcPasswordStrength
{
    Label = "新密码",
    ShortLength = 10,
    Rules = new[]
    {
        new ArcPasswordRule("length", "至少 10 个字符", value => value.Length >= 10),
        new ArcPasswordRule("number", "包含数字", value => value.Any(char.IsDigit))
    }
};

password.ValueChanged += (_, e) =>
{
    Submit.IsEnabled = e.Level >= 3;
};
